// Fission products, chapter 5 "Integrating it in TRISO-ATOPS" (lessons
// 39-46): the widgets. Each registers with Lesson.widget(id, make).
// Data: atops-data.js (generated by crates/dhoby-ghaut/examples/
// lesson_triso_atops from boon-lay's TRISO-ATOPS port). Models:
// atops-physics.js, and kernel-physics.js (chapter 3's exact Booth series).
// Plot helpers: plot-kit.js. Every computation is a table lookup or a short
// sum (well under a millisecond a frame), so no worker is needed here.
(function () {
  "use strict";
  var L = window.Lesson, css = L.css, el = L.el;
  var LP = window.LessonPlot, fmtT = LP.fmtT, sci = LP.sci, wrap = LP.wrap, Box = LP.Box, decTicks = LP.decTicks, linTicks = LP.linTicks, legend = LP.legend;
  var AD = function () { return window.ATOPS_DATA; };
  var AP = function () { return window.AtopsPhysics; };
  var GCOL = { NobleGas: "#2f7fd8", Halogen: "#7a4cc2", SpecialMetal: "#2a9d55", Silver: "#7f8c8d", Other: "#d4a017" };
  var GNAME = { NobleGas: "noble gas", Halogen: "halogen (+Se, Te)", SpecialMetal: "special metal", Silver: "silver (+Pd)", Other: "other" };
  function lerp(x, xs, ys) { if (x <= xs[0]) return ys[0]; for (var i = 1; i < xs.length; i++) if (x <= xs[i]) { var u = (x - xs[i - 1]) / (xs[i] - xs[i - 1]); return ys[i - 1] + u * (ys[i] - ys[i - 1]); } return ys[ys.length - 1]; }
  function nodeOf(name) { return AD().nodes.filter(function (n) { return n.name === name; })[0]; }

  // ─── 39: the big picture ──────────────────────────────────────────────
  var BOXES = [
    ["Inventory", "Each node's inventory of each nuclide, from a depletion code (an input).", null, "—"],
    ["D(T) per group", "diffusion_coefficient: one Arrhenius law per group, with lower clamps.", "crates/boon-lay/src/triso_atops_fork/diffusion/mod.rs::diffusion_coefficient", "lessons 15, 30"],
    ["<R/B> per group", "rb_fail: R/B correlation, Booth sphere, silver breakthrough or a fixed 1e-5.", "crates/boon-lay/src/triso_atops_fork/release_models/mod.rs::rb_fail", "lessons 16-19, 31"],
    ["× failed fraction", "release_rate: R/B × birth rate × the failure fractions the group sees.", "crates/boon-lay/src/triso_atops_fork/activities/source_terms.rs::release_rate", "lessons 33-37"],
    ["Graphite hold-up", "attenuation_factor: metals are delayed by the graphite; gases pass.", "crates/boon-lay/src/triso_atops_fork/release_models/steady_state.rs::attenuation_factor", "—"],
    ["Coolant pools", "circulating, plate-out, clean-up: first-order removal rates.", "crates/boon-lay/src/triso_atops_fork/normal_operation/mod.rs::normal_operation_node", "—"],
    ["Accident: ∫D dt", "integrate_diffusion_over_time, then Booth or breakthrough on the integral.", "crates/boon-lay/src/triso_atops_fork/release_models/mod.rs::release_fraction_transient", "lesson 37"],
    ["Venting", "coolant_release: gas leaves while the core heats; nothing once it cools.", "crates/boon-lay/src/triso_atops_fork/accident/mod.rs::coolant_release", "—"]
  ];
  function bigPicture(root) {
    var st = { pick: -1 };
    var frame = new L.Frame(root, {
      reset: function () { st.pick = -1; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var top = 54, cols = w >= 600 ? 4 : 2, rows = Math.ceil(BOXES.length / cols), gap = 16;
        var bw = (w - 16 - gap * (cols - 1)) / cols, bh = Math.min(70, (h - top - 30 - gap * (rows - 1)) / rows) * Math.min(zoom, 1.3);
        var pos = BOXES.map(function (b, k) {
          var r = Math.floor(k / cols), c = r % 2 ? cols - 1 - k % cols : k % cols; // snake order
          return { x: 8 + c * (bw + gap), y: top + r * (bh + gap) };
        });
        for (var k = 1; k < pos.length; k++) {
          var a = pos[k - 1], b = pos[k];
          var x0 = a.x + bw / 2, y0 = a.y + bh / 2, x1 = b.x + bw / 2, y1 = b.y + bh / 2;
          if (a.y === b.y) L.arrow(ctx, x0 + (x1 > x0 ? bw / 2 : -bw / 2), y0, x1 + (x1 > x0 ? -bw / 2 : bw / 2), y1, "#888");
          else L.arrow(ctx, x0, a.y + bh, x1, b.y, "#888");
        }
        ctx.font = "12px system-ui, sans-serif";
        BOXES.forEach(function (bx, k) {
          var p = pos[k];
          ctx.fillStyle = k === st.pick ? "#f3e6dc" : css("--panel", "#fff"); ctx.strokeStyle = k >= 6 ? "#b85c38" : "#2a9d55"; ctx.lineWidth = 2;
          ctx.fillRect(p.x, p.y, bw, bh); ctx.strokeRect(p.x, p.y, bw, bh);
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "bold 12px system-ui, sans-serif"; wrap(ctx, bx[0], p.x + 6, p.y + 16, bw - 12, 14);
          ctx.font = "10px system-ui, sans-serif"; ctx.fillStyle = css("--muted", "#5b636b"); ctx.fillText(bx[3] === "—" ? "" : "taught in " + bx[3], p.x + 6, p.y + bh - 6);
        });
        return st.pick >= 0 ? BOXES[st.pick][0] + ": " + BOXES[st.pick][1] : "Green: normal operation, per fuel node. Orange: the accident. Pick a box in the panel to read what it does.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Box", BOXES.map(function (b, k) { return [k, b[0]]; }), -1, function (v) { st.pick = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "Each box links into the Code Review map in the text below."));
      }
    });
    return frame;
  }

  // ─── 40: 84 nuclides, five groups ─────────────────────────────────────
  function groups(root) {
    var st = { only: "all" };
    var frame = new L.Frame(root, {
      reset: function () { st.only = "all"; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), top = 54, order = ["NobleGas", "Halogen", "SpecialMetal", "Silver", "Other"];
        var y = top, fs = Math.round(11 * Math.min(Math.max(zoom, 0.8), 1.6)), lh = fs + 9;
        ctx.font = fs + "px system-ui, sans-serif";
        order.forEach(function (g) {
          if (st.only !== "all" && st.only !== g) return;
          var list = A.nuclides.filter(function (n) { return n.group === g; });
          ctx.fillStyle = GCOL[g]; ctx.font = "bold " + fs + "px system-ui, sans-serif"; ctx.fillText(GNAME[g] + " (" + list.length + ")", 8, y + fs); y += lh;
          ctx.font = fs + "px system-ui, sans-serif";
          var x = 8;
          list.forEach(function (n) {
            var tw = ctx.measureText(n.name).width + 10;
            if (x + tw > w - 8) { x = 8; y += lh; }
            ctx.fillStyle = GCOL[g]; ctx.globalAlpha = 0.18; ctx.fillRect(x, y, tw, lh - 3); ctx.globalAlpha = 1;
            if (n.name === "Y-90" || n.name === "Y-91" || n.name === "Y-92") { ctx.strokeStyle = "#c0392b"; ctx.lineWidth = 2; ctx.strokeRect(x, y, tw, lh - 3); }
            ctx.fillStyle = css("--fg", "#1d2125"); ctx.fillText(n.name, x + 5, y + fs + 1);
            x += tw + 4;
          });
          y += lh + 4;
        });
        var cls = {}; A.nuclides.forEach(function (n) { cls[n.group + "|" + A.dClassNames[n.dClass]] = 1; });
        return "Group (colour) and chapter 3's diffusion class always agree: " + Object.keys(cls).map(function (k) { return k.replace("|", " → "); }).join("; ") + ". Red outline: yttrium, which the paper groups with Sr but the code treats as 'other'.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Show", [["all", "All 84"], ["NobleGas", "Noble gases"], ["Halogen", "Halogens"], ["SpecialMetal", "Special metals"], ["Silver", "Silver"], ["Other", "Other"]], st.only, function (v) { st.only = v; redraw(); });
      }
    });
    return frame;
  }

  // ─── 41: one diffusion law per group, with clamps ─────────────────────
  function atopsD(root) {
    var st = { mat: "kernel" };
    var COLS = ["#2f7fd8", "#7a4cc2", "#2a9d55", "#7f8c8d", "#d4a017"];
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), top = 54;
        var B = new Box(58, top, w - 12, h - 40, [300, 2400], [-30 + (zoom - 1) * 4, -6], false, true);
        B.frame(ctx, "temperature (°C)", "D (m²/s), " + st.mat, linTicks(300, 2400, 300), decTicks(B.yr[0], -6, 4));
        var leg = [], notes = [];
        A.dCurves.forEach(function (c, k) {
          var ys = c[st.mat], clamp = st.mat === "kernel" ? c.clampKernel : c.clampGraphite;
          if (clamp && clamp < 2400) {
            ctx.fillStyle = COLS[k]; ctx.globalAlpha = 0.08; ctx.fillRect(B.X(300), B.y0, B.X(clamp) - B.X(300), B.y1 - B.y0); ctx.globalAlpha = 1;
            notes.push(c.name + " held flat below " + clamp + " °C");
          }
          B.line(ctx, A.dGrid, ys, COLS[k], 2);
          leg.push([c.name, COLS[k]]);
        });
        if (st.mat === "kernel") { B.line(ctx, A.dGrid, A.dSicAg, "#7f8c8d", 2, [5, 4]); leg.push(["Ag in SiC", "#7f8c8d", [5, 4]]); }
        legend(ctx, leg, B.x0 + 4, B.y0 + 14, B.x1 - B.x0 - 8);
        if (st.mat === "kernel") { var x = B.X(1500); ctx.strokeStyle = "#2f7fd8"; ctx.setLineDash([2, 3]); ctx.beginPath(); ctx.moveTo(x, B.y0); ctx.lineTo(x, B.y1); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle = "#2f7fd8"; ctx.font = "10px system-ui, sans-serif"; ctx.fillText("Kr: new branch", x + 3, B.y1 - 6); }
        return (notes.length ? "Clamps found in the output: " + notes.join("; ") + "." : "No clamps in this material.") + " Shaded: the range where the code holds D at its lowest valid value instead of extrapolating.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Material", [["kernel", "Kernel (and SiC for Ag)"], ["graphite", "Graphite"]], st.mat, function (v) { st.mat = v; redraw(); });
      }
    });
    return frame;
  }

  // ─── 42: one release model per group ──────────────────────────────────
  function releaseModels(root) {
    var st = { mode: "rb" };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), top = 54, s = "";
        if (st.mode === "booth") {
          var B = new Box(58, top, w - 12, h - 40, [-16, 1], [-9 + (zoom - 1) * 2, 0], true, true);
          B.xr = [-16, 1];
          B.frame(ctx, "D t / a² (reduced time)", "fraction released", decTicks(-16, 1, 4), decTicks(B.yr[0], 0, 2));
          var exact = A.booth.x.map(function (x) { return window.KernelPhysics.boothF(x); });
          B.line(ctx, A.booth.x, exact, "#111", 2);
          B.line(ctx, A.booth.x, A.booth.long, "#c0392b", 2, [5, 4]);
          var yf = B.Y(A.booth.long[0]); ctx.fillStyle = "#c0392b"; ctx.font = "11px system-ui, sans-serif"; ctx.fillText("floor " + A.booth.long[0].toExponential(3), B.x0 + 6, yf - 4);
          legend(ctx, [["exact Booth (chapter 3)", "#111"], ["TRISO-ATOPS, " + A.booth.terms + " terms", "#c0392b", [5, 4]]], B.x0 + 4, B.y0 + 14, B.x1 - B.x0 - 8);
          s = "With " + A.booth.terms + " terms the series cannot go below " + A.booth.long[0].toExponential(3) + ": at small D t / a² the port, like upstream, over-states the release (gh:#385). Kept as upstream has it.";
        } else if (st.mode === "atten") {
          var B2 = new Box(58, top, w - 12, h - 40, [600, 1800], [0, 9], false, true);
          B2.frame(ctx, "graphite temperature (°C)", "attenuation factor", linTicks(600, 1800, 300), decTicks(0, 9, 2));
          [["Cs", "#7a4cc2"], ["Sr", "#2a9d55"], ["Ag", "#7f8c8d"]].forEach(function (c) { B2.line(ctx, A.rbT, A.attenuation[c[0]], c[1], 2); });
          ctx.strokeStyle = "#d4a017"; ctx.setLineDash([4, 3]); ctx.beginPath(); ctx.moveTo(B2.x0, B2.Y(1e8)); ctx.lineTo(B2.x1, B2.Y(1e8)); ctx.stroke(); ctx.setLineDash([]);
          legend(ctx, [["Cs", "#7a4cc2"], ["Sr", "#2a9d55"], ["Ag", "#7f8c8d"], ["cap, and every 'other' metal: 1e8", "#d4a017", [4, 3]]], B2.x0 + 4, B2.y0 + 14, B2.x1 - B2.x0 - 8);
          s = "The 4.5 mm of graphite between the fuel and the coolant delays metals: release into the coolant is divided by this factor (after 3 years). It falls to 1 as the graphite warms and fills up. Gases pass straight through.";
        } else {
          var B3 = new Box(58, top, w - 12, h - 40, [600, 1800], [-10 + (zoom - 1) * 2, 0], false, true);
          B3.frame(ctx, "fuel temperature (°C)", "<R/B> of a failed particle", linTicks(600, 1800, 300), decTicks(B3.yr[0], 0, 2));
          var leg = [];
          A.rb.forEach(function (r, k) { var col = r.group === "NobleGas" || r.group === "Halogen" ? (r.name === "Kr-88" ? "#2f7fd8" : r.name === "Xe-133" ? "#4aa3df" : "#7a4cc2") : r.group === "SpecialMetal" ? ["#2a9d55", "#1d7a42", "#6ab04c", "#a3cb38"][["Cs-137", "Cs-134", "Sr-90", "Sr-89"].indexOf(r.name)] : r.group === "Silver" ? (r.name === "Ag-110m" ? "#7f8c8d" : "#b2bec3") : "#d4a017";
            A3line(B3, ctx, A.rbT, r.rb, col, r.short ? [5, 3] : []); leg.push([r.name, col, r.short ? [5, 3] : []]); });
          legend(ctx, leg, B3.x0 + 4, B3.y0 + 14, B3.x1 - B3.x0 - 8);
          s = "Noble gases and halogens: a correlation fitted to AGR-3/4 gas releases. Cs and Sr: Booth on an equivalent sphere (short-lived dashed). Silver: breakthrough through SiC. Zr-95 ('other'): a fixed 1e-5.";
        }
        return s;
      },
      panel: function (body, redraw) {
        L.buttons(body, "Show", [["rb", "R/B by group"], ["booth", "The Booth floor"], ["atten", "Graphite hold-up"]], st.mode, function (v) { st.mode = v; redraw(); });
      }
    });
    function A3line(B, ctx, xs, ys, col, dash) { B.line(ctx, xs, ys, col, 2, dash); }
    return frame;
  }

  // ─── 43: normal operation per node ────────────────────────────────────
  function nodeW(root) {
    var st = { name: "Cs-137", mult: 0, src: "caseA" };
    var frame = new L.Frame(root, {
      reset: function () { st.mult = 0; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), n = nodeOf(st.name), c = A.caseA, top = 54;
        var f0 = { hm: c.fHM, sic: c.fSiC, inc: c.fInc, incSic: c.fIncSiC };
        var f = { hm: c.fHM, sic: c.fSiC, inc: st.src === "ff" ? A.phi1Eoi776 : c.fInc, incSic: c.fIncSiC };
        var k = Math.pow(10, st.mult); f = { hm: f.hm * k, sic: f.sic * k, inc: f.inc * k, incSic: f.incSic * k };
        var scale = AP().releaseScale(n.group, f, f0);
        var B = new Box(64, top, w - 12, h - 40, [600, 1200], [Math.log10(Math.min.apply(null, n.releaseVsT)) - 2, Math.log10(Math.max.apply(null, n.releaseVsT)) + 2], false, true);
        B.yr = [Math.floor(B.yr[0]), Math.ceil(B.yr[1])];
        B.frame(ctx, "node temperature (°C)", "release rate (atoms/s per Ci)", linTicks(600, 1200, 100), decTicks(B.yr[0], B.yr[1], 2));
        B.line(ctx, A.nodeT, n.releaseVsT, "#999", 1.5, [4, 3]);
        B.line(ctx, A.nodeT, n.releaseVsT.map(function (r) { return r * scale; }), GCOL[n.group], 2.5);
        var r900 = n.base[0] * scale; ctx.fillStyle = GCOL[n.group]; ctx.beginPath(); ctx.arc(B.X(900), B.Y(r900), 4, 0, 2 * Math.PI); ctx.fill();
        legend(ctx, [["MHTGR Case A fractions", "#999", [4, 3]], ["your fractions", GCOL[n.group]]], B.x0 + 4, B.y0 + 14, B.x1 - B.x0 - 8);
        var which = n.group === "NobleGas" || n.group === "Halogen" ? "f_HM + f_inc" : n.group === "Silver" ? "no failure fraction at all" : "f_HM + f_SiC + f_inc + f_inc,SiC";
        return st.name + " (" + GNAME[n.group] + ") uses " + which + ". At 900 °C: " + sci(r900) + " atoms/s per Ci, × " + scale.toPrecision(3) + " of Case A." + (st.src === "ff" ? " f_inc = " + sci(A.phi1Eoi776) + " from boon-lay fuel failure (lesson 36): far below Case A's 2.3e-5." : "");
      },
      panel: function (body, redraw) {
        L.buttons(body, "Nuclide", AD().nodes.map(function (n) { return [n.name, n.name]; }), st.name, function (v) { st.name = v; redraw(); });
        L.buttons(body, "In-service f_inc from", [["caseA", "MHTGR Case A (2.3e-5)"], ["ff", "boon-lay fuel failure"]], st.src, function (v) { st.src = v; redraw(); });
        L.slider(body, "Scale every failure fraction", -2, 2, 0.1, 0, function (v) { st.mult = v; redraw(); return "× " + Math.pow(10, v).toPrecision(2); });
      }
    });
    return frame;
  }

  // ─── 44: into the coolant ─────────────────────────────────────────────
  function pools(root) {
    var st = { name: "Cs-137", hps: false };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), n = nodeOf(st.name), v = st.hps ? n.hps : n.base, top = 54, ci = n.lambda / 3.7e10;
        var items = [["graphite", v[2] * ci], ["circulating", v[3] * ci], ["plated out", v[4] * ci], ["cleaned up", v[5] * ci]];
        var pos = items.filter(function (i) { return i[1] > 0; }).map(function (i) { return Math.log10(i[1]); });
        var hi = pos.length ? Math.ceil(Math.max.apply(null, pos)) + 1 : 0, lo = hi - 12 / Math.max(zoom, 0.5);
        var B = new Box(64, top, w - 12, h - 40, [-0.5, 3.5], [lo, hi], false, true);
        B.frame(ctx, "", "activity (Ci per Ci of inventory)", [], decTicks(lo, hi, 2));
        var why = { graphite: n.group === "NobleGas" || n.group === "Halogen" ? "gases are not held in graphite" : "", "plated out": n.group === "NobleGas" ? "noble gases do not plate out" : "", "cleaned up": !st.hps ? "no clean-up system" : n.group === "NobleGas" || n.group === "Halogen" ? "" : "the clean-up system does not take metals" };
        items.forEach(function (it, k) {
          var x = B.X(k - 0.35), xw = B.X(k + 0.35) - x;
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "11px system-ui, sans-serif"; ctx.fillText(it[0], x, B.y1 + 13);
          if (it[1] > 0) { var y = B.Y(it[1]); ctx.fillStyle = GCOL[n.group]; ctx.fillRect(x, y, xw, B.y1 - y); }
          else { ctx.strokeStyle = "#999"; ctx.setLineDash([4, 3]); ctx.strokeRect(x, B.y0 + 20, xw, B.y1 - B.y0 - 20); ctx.setLineDash([]); ctx.fillStyle = "#777"; ctx.font = "10px system-ui, sans-serif"; wrap(ctx, "0: " + (why[it[0]] || "zero"), x + 2, B.y0 + 36, xw - 4, 12); }
        });
        return st.name + " after 40 years of Case A, one node at 900 °C: graphite " + sci(items[0][1]) + ", circulating " + sci(items[1][1]) + ", plated out " + sci(items[2][1]) + ", cleaned up " + sci(items[3][1]) + " Ci per Ci in the fuel. Dashed boxes: terms the model sets to zero, and why.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Nuclide", AD().nodes.map(function (n) { return [n.name, n.name]; }), st.name, function (v) { st.name = v; redraw(); });
        L.toggle(body, "Clean-up (helium purification) system", st.hps, function (v) { st.hps = v; redraw(); });
      }
    });
    return frame;
  }

  // ─── 45: accidents ────────────────────────────────────────────────────
  function accidentW(root) {
    var st = { pi: 1, name: "Cs-137" };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var A = AD(), acc = A.accidents[st.pi], n = acc.nuclides.filter(function (x) { return x.name === st.name; })[0], top = 54;
        var T = new Box(58, top, w - 12, top + (h - top) * 0.28, [0, 300], [800, 1900], false, false);
        T.frame(ctx, "", "T (°C)", [], linTicks(900, 1800, 300));
        T.line(ctx, acc.hours, acc.tC, "#b85c38", 2);
        var B = new Box(58, T.y1 + 22, w - 12, h - 30, [0, 300], [0, 1], false, false);
        B.frame(ctx, "hours", "fraction", linTicks(0, 300, 50), linTicks(0, 1, 0.25));
        B.line(ctx, acc.hours, n.rfKernel, "#2a9d55", 2);
        B.line(ctx, acc.hours, n.rfGraphite, "#7a4cc2", 2, [5, 4]);
        B.line(ctx, acc.hours, n.vent, "#111", 2.5);
        var lastVent = -1; n.vent.forEach(function (v, k) { if (v !== null) lastVent = k; });
        if (lastVent >= 0 && lastVent < acc.hours.length - 1) { ctx.fillStyle = "#999"; ctx.globalAlpha = 0.12; ctx.fillRect(B.X(acc.hours[lastVent]), B.y0, B.x1 - B.X(acc.hours[lastVent]), B.y1 - B.y0); ctx.globalAlpha = 1; ctx.fillStyle = "#555"; ctx.font = "11px system-ui, sans-serif"; wrap(ctx, "cooling: the gas contracts, nothing more leaves", B.X(acc.hours[lastVent]) + 4, B.y0 + 40, B.x1 - B.X(acc.hours[lastVent]) - 8, 13); }
        legend(ctx, [["out of the kernel", "#2a9d55"], ["out of the graphite", "#7a4cc2", [5, 4]], ["coolant vented (heating only)", "#111"]], B.x0 + 4, B.y0 + 14, B.x1 - B.x0 - 8);
        var j = 20;
        return st.name + ", heat-up from 900 to " + acc.peak + " °C (ILLUSTRATIVE): at the end of the hold " + (100 * n.rfKernel[j]).toPrecision(3) + " % has left the kernels, " + (100 * n.rfGraphite[j]).toPrecision(3) + " % of the graphite's share has left the graphite, and " + (100 * n.vent[j]).toPrecision(3) + " % of the coolant has been pushed out.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Peak temperature", AD().accidents.map(function (a, k) { return [k, a.peak + " °C"]; }), st.pi, function (v) { st.pi = v; redraw(); });
        L.buttons(body, "Nuclide", AD().accidents[0].nuclides.map(function (n) { return [n.name, n.name]; }), st.name, function (v) { st.name = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "The heat-up is the same prescribed shape as lesson 36 (50 h up, 50 h held, 200 h down), from 900 °C. One node; MHTGR Case A geometry."));
      }
    });
    return frame;
  }

  // ─── 46: the ladder ───────────────────────────────────────────────────
  function ladder(root) {
    var RUNGS = [
      ["Finite-element particle (BISON-style)", "not built", "theory step 5"],
      ["Multilayer diffusion on a mesh (FRESCO-style)", "not built", "lesson 32"],
      ["Random walk through every layer", "boon-lay; impractical for a whole particle", "lesson 32"],
      ["Layered walk / exact mean exit time", "this site's teaching models", "lesson 32"],
      ["Booth equivalent sphere per group", "TRISO-ATOPS", "lessons 16-18, 42"],
      ["Empirical R/B correlation", "TRISO-ATOPS (gases, halogens)", "lesson 42"],
      ["Fixed nominal value", "TRISO-ATOPS ('other')", "lesson 42"]
    ];
    var st = { pick: 4 };
    var frame = new L.Frame(root, {
      reset: function () { st.pick = 4; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var top = 54, n = RUNGS.length, rh = Math.min(48, (h - top - 20) / n) * Math.min(zoom, 1.3);
        RUNGS.forEach(function (r, k) {
          var y = top + k * rh, built = r[1] !== "not built";
          ctx.fillStyle = k === st.pick ? "#f3e6dc" : css("--panel", "#fff"); ctx.strokeStyle = built ? "#2a9d55" : "#999"; ctx.lineWidth = 2; ctx.setLineDash(built ? [] : [4, 3]);
          var inset = 8 + k * Math.min(10, w / 60);
          ctx.fillRect(inset, y, w - 2 * inset, rh - 6); ctx.strokeRect(inset, y, w - 2 * inset, rh - 6); ctx.setLineDash([]);
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "bold 12px system-ui, sans-serif"; ctx.fillText(r[0], inset + 8, y + 16);
          ctx.font = "11px system-ui, sans-serif"; ctx.fillStyle = css("--muted", "#5b636b"); ctx.fillText(r[1] + " · " + r[2], inset + 8, y + rh - 12);
        });
        return "Top: most physics, most cost. Bottom: least. Dashed: not built in the workspace. TRISO-ATOPS lives on the bottom three rungs.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Rung", RUNGS.map(function (r, k) { return [k, r[0]]; }), st.pick, function (v) { st.pick = v; redraw(); });
      }
    });
    return frame;
  }

  // Numbers in the prose, bound by data-ad="...".
  function fillAd() {
    var A = AD(), c = A.caseA, cs = nodeOf("Cs-137"), kr = nodeOf("Kr-88");
    var count = function (g) { return String(A.nuclides.filter(function (n) { return n.group === g; }).length); };
    var curve = function (z) { return A.dCurves.filter(function (d) { return d.z === z; })[0]; };
    var acc = A.accidents[1], accCs = acc.nuclides.filter(function (n) { return n.name === "Cs-137"; })[0];
    var map = {
      nNuclides: String(A.nuclides.length), nNoble: count("NobleGas"), nHalogen: count("Halogen"), nSpecial: count("SpecialMetal"), nSilver: count("Silver"), nOther: count("Other"),
      csClampK: curve(55).clampKernel + " °C", csClampG: curve(55).clampGraphite + " °C", srClampK: curve(38).clampKernel + " °C", srClampG: curve(38).clampGraphite + " °C", agClampG: curve(47).clampGraphite + " °C",
      boothFloor: A.booth.long[0].toExponential(3), rmsR: (Math.sqrt((c.r * c.r + c.aGrain * c.aGrain) / 2) * 1e6).toFixed(0) + " µm", rmsD: (Math.sqrt((4 * c.r * c.r + 4 * c.aGrain * c.aGrain) / 2) * 1e6).toFixed(0) + " µm", boothTerms: String(A.booth.terms), aBooth: (c.aBooth * 1e6).toFixed(1) + " µm", r: (c.r * 1e6).toFixed(0) + " µm", aGrain: (c.aGrain * 1e6).toFixed(0) + " µm",
      phi1: sci(A.phi1Eoi776), bridgeKr: (kr.bridged[0] / kr.base[0]).toFixed(3), bridgeCs: (cs.bridged[0] / cs.base[0]).toFixed(3),
      vent1600: (100 * accCs.vent[20]).toFixed(1) + " %", ventIdeal: (100 * (1 - (900 + 273.15) / (1600 + 273.15))).toFixed(1) + " %", rfCs1600: (100 * accCs.rfKernel[20]).toFixed(1) + " %"
    };
    document.querySelectorAll("[data-ad]").forEach(function (n) { var k = n.getAttribute("data-ad"); if (k in map) n.textContent = map[k]; });
  }
  L.widget("ad-numbers", fillAd);
  L.widget("atops-map", bigPicture);
  L.widget("atops-groups", groups);
  L.widget("atops-d", atopsD);
  L.widget("atops-release", releaseModels);
  L.widget("atops-node", nodeW);
  L.widget("atops-pools", pools);
  L.widget("atops-accident", accidentW);
  L.widget("atops-ladder", ladder);
})();
